#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <stdexcept>

struct Token {
    char clase;
    int valor;
};

Token leer_token(std::istringstream& entrada) {
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') {
            continue;
        }
        if (actual >= '0' && actual <= '9') {
            int valor = actual - '0';
            while (entrada.get(actual)) {
                if (actual >= '0' && actual <= '9') {
                    valor = valor * 10 + (actual - '0');
                    if (valor > 99) {
                        throw std::runtime_error("Numero fuera de dominio");
                    }
                } else {
                    entrada.putback(actual);
                    if (!entrada) {
                        throw std::runtime_error("No se pudo conservar el caracter");
                    }
                    return Token{'n', valor};
                }
            }
            if (entrada.bad() || !entrada.eof()) {
                throw std::runtime_error("Fallo del flujo");
            }
            return Token{'n', valor};
        }
        if (actual == '+' || actual == '-' || actual == '*'
                || actual == '/' || actual == '%' || actual == '(' || actual == ')'
                || actual == ';') {
            return Token{actual, 0};
        }
        throw std::runtime_error("Caracter no admitido");
    }
    if (entrada.bad() || !entrada.eof()) {
        throw std::runtime_error("Fallo del flujo");
    }
    return Token{'f', 0};
}

bool token_valido(Token token) {
    if (token.clase == 'n') {
        return token.valor >= 0 && token.valor <= 99;
    }
    const bool signo = token.clase == '+' || token.clase == '-'
        || token.clase == '*' || token.clase == '/' || token.clase == '%'
        || token.clase == '(' || token.clase == ')' || token.clase == ';';
    return token.valor == 0 && (signo || token.clase == 'f');
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {}

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(Token token) {
        if (lleno_) {
            throw std::runtime_error("Buffer ocupado");
        }
        if (!token_valido(token)) {
            throw std::runtime_error("Token invalido");
        }
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion();

    bool tiene_pendiente() const {
        return lleno_;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{'f', 0};
};

bool Lector_tokens::descartar_operacion() {
    if (entrada_.bad()) {
        throw std::runtime_error("Flujo irrecuperable");
    }
    if (lleno_) {
        const Token pendiente = guardado_;
        lleno_ = false;
        if (pendiente.clase == ';') {
            return true;
        }
        if (pendiente.clase == 'f') {
            return false;
        }
    }
    entrada_.clear();
    char actual = '?';
    while (entrada_.get(actual)) {
        if (actual == ';') {
            return true;
        }
    }
    if (entrada_.bad() || !entrada_.eof()) {
        throw std::runtime_error("Fallo al recuperar");
    }
    return false;
}

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Resultado fuera de dominio");
    }
    return candidato;
}

int leer_expresion(Lector_tokens& lector, int profundidad);

int leer_unidad(Lector_tokens& lector, int profundidad) {
    if (profundidad > 8) {
        throw std::runtime_error("Anidamiento excesivo");
    }
    const Token token = lector.leer();
    if (token.clase == 'n') {
        return token.valor;
    }
    if (token.clase == '+') {
        return leer_unidad(lector, profundidad + 1);
    }
    if (token.clase == '-') {
        const int valor = leer_unidad(lector, profundidad + 1);
        return resultado_en_dominio(-valor);
    }
    if (token.clase == '(') {
        const int valor = leer_expresion(lector, profundidad + 1);
        const Token cierre = lector.leer();
        if (cierre.clase != ')') {
            lector.devolver(cierre);
            throw std::runtime_error("Se esperaba )");
        }
        return valor;
    }
    lector.devolver(token);
    throw std::runtime_error("Se esperaba una unidad");
}

int leer_termino(Lector_tokens& lector, int profundidad) {
    int izquierda = leer_unidad(lector, profundidad);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '*') {
            const int derecha = leer_unidad(lector, profundidad);
            izquierda = resultado_en_dominio(izquierda * derecha);
        } else if (token.clase == '/' || token.clase == '%') {
            const int derecha = leer_unidad(lector, profundidad);
            if (derecha == 0) {
                throw std::runtime_error("Divisor cero");
            }
            if (token.clase == '/')
                izquierda = resultado_en_dominio(izquierda / derecha);
            else
                izquierda = resultado_en_dominio(izquierda % derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_expresion(Lector_tokens& lector, int profundidad) {
    int izquierda = leer_termino(lector, profundidad);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '+') {
            const int derecha = leer_termino(lector, profundidad);
            izquierda = resultado_en_dominio(izquierda + derecha);
        } else if (token.clase == '-') {
            const int derecha = leer_termino(lector, profundidad);
            izquierda = resultado_en_dominio(izquierda - derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_operacion(Lector_tokens& lector) {
    const int resultado = leer_expresion(lector, 0);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
    return resultado;
}

int sumar_historial(const std::vector<int>& valores) {
    int total = 0;
    for (int valor : valores) {
        total += valor;
    }
    return total;
}

int main() {
    const std::string texto{"19%6;-19%6;25/4%3;"};
    Lector_tokens lector{texto};
    std::vector<int> aceptados;
    int rechazadas = 0;
    bool continuar = true;
    while (continuar) {
        try {
            const Token inicio = lector.leer();
            if (inicio.clase == 'f') {
                continuar = false;
                continue;
            }
            lector.devolver(inicio);
            const int resultado = leer_operacion(lector);
            aceptados.push_back(resultado);
            std::cout << "Valor: " << resultado << "\n";
        } catch (const std::runtime_error& error) {
            ++rechazadas;
            std::cout << "Error: " << error.what() << "\n";
            try {
                continuar = lector.descartar_operacion();
            } catch (const std::runtime_error& fallo) {
                std::cout << "Recuperacion detenida: " << fallo.what() << "\n";
                continuar = false;
            }
        }
    }
    const int suma = sumar_historial(aceptados);
    std::cout << "Aceptadas: " << aceptados.size() << "\n";
    std::cout << "Rechazadas: " << rechazadas << "\n";
    std::cout << "Suma: " << suma << "\nHistorial:";
    for (int valor : aceptados) {
        std::cout << " " << valor;
    }
    return 0;
}

